package ai.taskforge.api;
import ai.taskforge.domain.*; import ai.taskforge.repo.*; import ai.taskforge.service.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/workflows") public class WorkflowController { private final WorkflowRepository workflows;private final WorkflowStepRepository steps;private final WorkflowInstanceRepository instances;private final CurrentUser current;private final AuditService audit;private final WorkflowExecutionService execution;public WorkflowController(WorkflowRepository w,WorkflowStepRepository s,WorkflowInstanceRepository i,CurrentUser c,AuditService a,WorkflowExecutionService e){workflows=w;steps=s;instances=i;current=c;audit=a;execution=e;} record StepInput(@NotBlank String name,String assigneeRole,boolean approvalRequired,@Min(1) int slaHours){} record WorkflowInput(@NotBlank String name,String description,@NotEmpty List<StepInput> steps){} record StepView(UUID id,int order,String name,String assigneeRole,boolean approvalRequired,int slaHours){} record View(UUID id,String name,String description,boolean active,List<StepView> steps){} record StartInput(@NotNull UUID taskId){} record InstanceView(UUID id,UUID workflowId,UUID taskId,String workflow,String task,WorkflowInstanceStatus status,int currentStepOrder){} @GetMapping List<View> list(){return workflows.findAll().stream().map(this::view).toList();} @GetMapping("/instances") @PreAuthorize("hasAnyRole('ADMIN','MANAGER')") List<InstanceView> instances(){return instances.findAllBy().stream().map(this::instance).toList();} @PostMapping @PreAuthorize("hasAnyRole('ADMIN','MANAGER')") View create(@Valid @RequestBody WorkflowInput in){var w=workflows.save(new Workflow(in.name(),in.description(),current.get()));int order=1;for(var s:in.steps())steps.save(new WorkflowStep(w,order++,s.name(),s.assigneeRole(),s.approvalRequired(),s.slaHours()));audit.record(current.get(),"WORKFLOW_CREATED","WORKFLOW",w.getId(),null,w.getName());return view(w);} @PostMapping("/{id}/instances") @PreAuthorize("hasAnyRole('ADMIN','MANAGER')") InstanceView start(@PathVariable UUID id,@Valid @RequestBody StartInput in){return instance(execution.start(id,in.taskId(),current.get()));} @PostMapping("/instances/{id}/advance") @PreAuthorize("hasAnyRole('ADMIN','MANAGER')") InstanceView advance(@PathVariable UUID id){return instance(execution.advance(id,current.get()));} private View view(Workflow w){return new View(w.getId(),w.getName(),w.getDescription(),w.isActive(),steps.findByWorkflowIdOrderByStepOrder(w.getId()).stream().map(s->new StepView(s.getId(),s.getStepOrder(),s.getName(),s.getAssigneeRole(),s.isApprovalRequired(),s.getSlaHours())).toList());} private InstanceView instance(WorkflowInstance i){return new InstanceView(i.getId(),i.getWorkflow().getId(),i.getTask().getId(),i.getWorkflow().getName(),i.getTask().getTitle(),i.getStatus(),i.getCurrentStepOrder());} }
